// Captured measurement helpers from the supported cua_repl browser session.
// Require the bound localhost:4179 tab, finalAppCdp capability, manifest and sample arrays.
// DOM interactions are performed with timingAppTab.playwright.
const copyReadReady = async()=>{const r=await finalAppCdp.send('Runtime.evaluate',{expression:`new Promise(resolve=>{const started=performance.now();const check=()=>{const root=document.querySelector('#pf-app,[data-timing-source-detail]');if(root&&root.dataset.timingReady){requestAnimationFrame(()=>requestAnimationFrame(()=>resolve({url:location.href,entry:document.querySelector('script[type="module"]')?.getAttribute('src'),ready:root.dataset.timingReady,navigationMs:Number(root.dataset.timingNavigationMs),measurements:JSON.parse(root.dataset.timingMeasurements||'[]'),width:innerWidth,height:innerHeight,overflow:document.documentElement.scrollWidth>innerWidth,brokenImages:[...document.images].filter(i=>i.getBoundingClientRect().width>0&&(!i.complete||!i.naturalWidth)).map(i=>i.src),text:root.innerText})));return;}if(performance.now()-started>3000){resolve({error:'ready timeout',text:root?.innerText});return;}requestAnimationFrame(check)};check()})`,awaitPromise:true,returnByValue:true});return r.result.value};
const copyAction = async(selector,key,iteration,expected)=>{await timingAppTab.playwright.locator(selector).click();const r=await copyReadReady(),metric=r.measurements.at(-1);if(r.entry!=='/assets/index-DyHIx5_W.js'||r.error||r.brokenImages.length||r.overflow||!metric||!Number.isFinite(metric.elapsedMs)||expected&&!r.text.includes(expected))throw new Error(JSON.stringify({key,metric,error:r.error,expected}));copyInteractionSamples.push({key,iteration,url:r.url,entry:r.entry,width:r.width,height:r.height,elapsedMs:metric.elapsedMs,action:metric.action,text:iteration===0?r.text:undefined,overflow:r.overflow,brokenImages:r.brokenImages});await timingAppTab.getAXState({emit:false})};
const copyReadNative = async(native)=>{const cdp=await native.capabilities.get('cdp');const r=await cdp.send('Runtime.evaluate',{expression:`new Promise(resolve=>{const check=()=>{const root=document.querySelector('[data-timing-source-detail]');if(root?.dataset.timingReady){requestAnimationFrame(()=>requestAnimationFrame(()=>resolve({url:location.href,entry:document.querySelector('script[type="module"]')?.getAttribute('src'),text:root.innerText,ready:root.dataset.timingReady,navigationMs:Number(root.dataset.timingNavigationMs),origin:performance.timeOrigin})));return}requestAnimationFrame(check)};check()})`,awaitPromise:true,returnByValue:true});return r.result.value};
